definitions:
def MixtureRegionMAC3 (n k lo hi : ℕ) : Prop :=
 hi ≤ k ∧ k+2 ≤ n+lo ∧
 (hi-lo)*(hi-lo-1)*(n+2) ≤ 2*(k-hi+2)*(n+lo-k)

def DiagonalRegionMAC3 (a b i j : ℕ) : Prop :=
 ∃ r, i+j+2+r=a+b-1 ∧ r ≤ i ∧ r ≤ j ∧
   r*(r-1)*(a+b-1-2*r+2) ≤ 2*(i-r+2)*(j-r+2)

def VarianceRegionMAC3 (n k lo hi : ℕ) : Prop :=
 lo ≤ hi ∧ hi ≤ k ∧ k+2 ≤ n+lo ∧
 (n+2)*(hi-lo)^2 ≤ 4*(k-hi+2)*(n+lo-k)

def DiagonalVarianceMAC3 (a b i j : ℕ) : Prop :=
 ∃ r, i+j+2+r=a+b-1 ∧ r ≤ i ∧ r ≤ j ∧
   (a+b-1-2*r+2)*r^2 ≤ 4*(i-r+2)*(j-r+2)
